CREATE TABLE "public"."service_orders" (
  "service_order_id"     bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "job_id"               bigint                   NOT NULL,
  "service_order_number" text                     NOT NULL,
  "date_entered"         timestamp with time zone NOT NULL DEFAULT now(),
  "due_date"             date,
  "completed_at"         timestamp with time zone,
  "installer_id"         integer,
  "service_type"         text,
  "service_by"           text,
  "hours_estimated"      integer,
  "comments"             text,
  "service_type_detail"  text,
  "service_by_detail"    text,
  "chargeable"           boolean                  DEFAULT false,
  "is_warranty_so"       boolean                  DEFAULT false,
  "warranty_order_cost"  numeric,
  "installer_requested"  boolean                  DEFAULT false,
  "created_by"           text,
  "updated_at"           timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "service_orders_installer_id_fkey" FOREIGN KEY (installer_id) REFERENCES public.installers(installer_id) ON DELETE SET NULL,
  CONSTRAINT "service_orders_job_id_fkey" FOREIGN KEY (job_id) REFERENCES public.jobs(id) ON DELETE CASCADE,
  CONSTRAINT "service_orders_pkey" PRIMARY KEY (service_order_id),
  CONSTRAINT "service_orders_service_order_number_key" UNIQUE (service_order_number)
);

ALTER TABLE "public"."service_orders"
  ENABLE ROW LEVEL SECURITY;

CREATE INDEX idx_service_orders_job_id ON public.service_orders USING btree (job_id);

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.service_orders
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable delete for admin and service" ON "public"."service_orders"
  FOR DELETE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'service'::text, 'installation'::text])));

CREATE POLICY "Enable insert for service editors" ON "public"."service_orders"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'installation'::text, 'service'::text])));

CREATE POLICY "Enable read access for authenticated users" ON "public"."service_orders"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for service editors" ON "public"."service_orders"
  FOR UPDATE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'installation'::text, 'service'::text])));

REVOKE ALL ON SEQUENCE "public"."service_orders_service_order_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."service_orders_service_order_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."service_orders_service_order_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."service_orders_service_order_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."service_orders_service_order_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."service_orders_service_order_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."service_orders_service_order_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."service_orders_service_order_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."service_orders" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."service_orders" TO "service_role";

REVOKE ALL ON TABLE "public"."service_orders" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."service_orders" TO "postgres";
